-- الترجمة الإنجليزية لنص المالك (٢٠٢٦-١٠-٢٨)، نفس البنود وترتيبها.
update public.app_config set value = $j${"title": "Privacy & Use", "subtitle": "Privacy Policy and Terms and Rules of Use", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "Privacy Policy", "items": [{"id": "collect", "title": "Collection of Personal Data", "lines": ["The Al-Mohammad Ali Family app collects the personal data required to create a user account and verify the user's mobile phone number. This includes full name, mobile phone number, date of birth, gender, and profile photo, all of which are mandatory to complete registration.", "Users may optionally add their email address.", "The mobile phone number is used to sign in by sending a verification code to the registered number. Verifying ownership of a phone number does not, by itself, constitute verification of personal identity or of a claimed family relationship.", "Personal data is stored and processed only to the extent necessary to create and manage the account and to provide the app's services, in accordance with this Privacy Policy."]}, {"id": "relatives", "title": "Data on Family Members and Relatives", "lines": ["The Al-Mohammad Ali Family app retains data about family members and their relatives in order to document the family tree, preserve family ties, and make family information easier to access.", "This data includes names, family relationships, dates of birth and death, photos, and other family information required by the app's services.", "This data may be drawn from family sources, genealogical charts, and historical documents, or added by users in accordance with the permissions established in the app.", "Access to the data displayed in the family tree, including data relating to living persons, is limited to approved members, subject to the controls established to protect privacy.", "Users may submit requests to add or amend data on family members. Such requests are subject to review and approval by the app administration before they take effect.", "When submitting data, users must respect the privacy of others and must not add personal information or photos without the consent of the persons concerned or another lawful basis that permits it.", "The privacy of living persons and minors is taken into account when their data is collected or displayed in the family tree. Information is displayed only to the extent necessary to fulfil the app's purposes, in accordance with the established permissions and the lawful basis for processing.", "The app does not create accounts for children under the age of thirteen (13). Their data is limited to what their parents or guardians add to the family tree in accordance with the established controls.", "Data subjects or, where applicable, the parents or guardians of minors may request that data be corrected, updated, hidden, or deleted. Such requests are reviewed in accordance with the established controls and applicable regulations."]}, {"id": "auto", "title": "Automatically Collected Data", "lines": ["The Al-Mohammad Ali Family app automatically collects certain technical data while the app is in use, including device type and operating system, user activity logs, sign-in attempts, error and crash reports, and statistics on usage of and interaction with the app's sections and services.", "This data is used to strengthen app security and protect user accounts, monitor performance, detect and fix technical problems, and analyse service usage in order to develop the services and improve the user experience.", "The app does not collect the user's geographic location for tracking or location purposes.", "The app does not track users across third-party apps or websites, and does not share their data with data brokers or advertising networks.", "The app accesses the device camera or photo library only when the user chooses to take or upload a photo and after the user grants the necessary permission in the device settings. The user may withdraw this permission at any time."]}, {"id": "why", "title": "Purposes of Data Collection and Use", "lines": ["The Al-Mohammad Ali Family app collects and processes personal data for the purposes necessary to provide its services and manage its operations, including creating and managing user accounts, verifying phone numbers, documenting the family tree and family ties, managing news, events, and posts, and sending notifications related to the app's services.", "Data is also used to strengthen account security, protect information, monitor performance, resolve technical faults, and analyse service usage in order to develop the app and improve the user experience.", "The app allows family members to submit announcements about non-commercial family events and activities. Such announcements are subject to prior review and approval by the app administration before publication, in accordance with the established controls.", "The app does not permit members' data to be used for commercial advertising, marketing, or ad targeting, and does not sell users' personal data or give advertisers access to it."]}, {"id": "who", "title": "Access to Personal Data", "lines": ["Access to the data and information displayed in the Al-Mohammad Ali Family app is limited to approved family members, in accordance with the permissions and privacy settings established in the app.", "Users may control the visibility of their profile data, including their profile photo, date of birth, and other information, through the privacy settings available to them.", "Users may show or hide their mobile phone number from approved family members. This does not affect the use of the number for signing in and account management.", "Authorised administrators of the app may access only the data necessary to perform their duties, including managing memberships, reviewing requests and reports, and moderating content. They must keep such information confidential and must not use it beyond the authorised purposes."]}, {"id": "share", "title": "Sharing Data with Service Providers", "lines": ["The Al-Mohammad Ali Family app is committed to protecting users' personal data and does not sell it or share it with third parties for marketing or commercial advertising purposes.", "The app relies on the technical service providers needed to operate it and deliver its services, including Supabase and Firebase for data management and related technical functions, Apple for push notifications, and SMS providers for verifying phone numbers and completing sign-in.", "Data shared with service providers is limited to the information needed to provide the relevant services, and appropriate measures are taken to keep it confidential and protect it from unauthorised access, use, or disclosure.", "Service providers with whom data is shared must provide a level of protection similar or equivalent to that set out in this Policy and may not use the data for any purpose other than providing the relevant service.", "Personal data may be stored or processed on servers located outside the State of Kuwait, depending on the hosting locations and technical infrastructure of the service providers, subject to data protection requirements and applicable regulations.", "Data may be disclosed to the competent authorities where required by law or by orders issued by the competent authorities."]}, {"id": "otp", "title": "Sign-In and Account Protection", "lines": ["The Al-Mohammad Ali Family app uses mobile phone sign-in, sending a one-time verification code (OTP) by text message (SMS) to the registered number.", "The verification code may be used only once and expires five minutes after it is issued.", "The app applies security measures to limit attempts to enter incorrect verification codes, helping to protect user accounts and prevent unauthorised access.", "Users must keep their verification code confidential, must not share it with others, and must notify the app administration if they suspect any attempt to gain unauthorised access to their account."]}, {"id": "security", "title": "Information Security and Data Protection", "lines": ["The Al-Mohammad Ali Family app protects users' personal data by applying appropriate technical and organisational measures to reduce the risk of unauthorised access to, or unlawful use, alteration, or disclosure of, information.", "Data is transmitted between the app and its servers over encrypted connections using secure communication protocols (HTTPS/TLS), and is stored and processed using approved technical services, including Supabase and Firebase.", "The app uses a permissions system that defines the levels of access granted to users, moderators, and administrators, ensuring that viewing and managing data is restricted according to the duties and permissions assigned to each group.", "Measures are also applied to protect stored photos and files and to restrict access to them by unauthorised persons.", "Although appropriate security measures are taken, absolute protection of data against all technical risks and threats cannot be guaranteed."]}, {"id": "delete", "title": "Deletion of Account and Personal Data", "lines": ["Users may request deletion of their account through the dedicated option in the Al-Mohammad Ali Family app settings. The request is referred to the app administration, which will take the necessary steps to complete the deletion within no more than seven (7) calendar days from the date the request is received.", "Once account deletion is complete, the personal data associated with the account is removed, including the mobile phone number, email address, profile photo, and posts and comments, subject to any legal obligations that require certain data to be retained.", "Deleting an account does not require removing all information about the user from the family tree. The name and family relationship may be retained to the extent necessary to preserve the lineage, provided there is a lawful basis for retaining this information.", "Data subjects may submit a separate request to correct, hide, or delete their information in the family tree. Data that is the subject of a request to hide or delete is temporarily hidden from other members while the request is under review, until an appropriate decision is made in accordance with the established controls and applicable regulations.", "Users may withdraw their consent to the processing of their data at any time by changing the privacy settings in the app, turning off notifications in the device settings, or requesting deletion of their account. Withdrawal of consent does not affect the lawfulness of processing carried out before it was withdrawn.", "The app does not retain personal data for longer than necessary to fulfil the purposes for which it was collected, unless a legal obligation or lawful basis permits it to be retained for a longer period.", "Retention periods for usage logs, technical data, and backups are determined by the nature of the data, the purpose of processing, security requirements, and applicable regulations. Such data is deleted or anonymised once it is no longer needed, in accordance with the established technical procedures.", "The app administration will inform the user of the outcome of a request to delete the account or personal data through the available means of communication, with due regard for the rights of data subjects and applicable regulations."]}, {"id": "privacy_contact", "title": "Contacting the App Administration", "lines": ["Users may contact the Al-Mohammad Ali Family app administration regarding enquiries, complaints, privacy requests, data correction, account deletion, and reports of violations via the official email address: info@almohali.com", "Contacting the administration by email is not an additional requirement for requesting account deletion, as a deletion request can be started directly from within the app in accordance with this Policy."]}]}, {"key": "terms", "title": "Terms and Rules of Use", "items": [{"id": "eligibility", "title": "Scope of Use and Membership", "lines": ["The Al-Mohammad Ali Family app is intended for members of the family and their relatives, in accordance with the membership rules established by the app administration. It aims to document family ties, strengthen communication among family members, and provide services and information related to family affairs.", "Joining the app is subject to registration and verification of applicants' eligibility. Creating an account or completing registration does not constitute automatic approval of membership; the app administration reviews applications to join, verifies applicants' eligibility, and approves their membership in accordance with the established rules.", "Persons aged thirteen (13) or over but under eighteen (18) may create their own account in the app, provided that explicit, documented consent is obtained from their parent or guardian before the account is activated, in addition to the app administration's approval of the membership application.", "Persons under the age of thirteen (13) may not create an account in the app. They may be included in the family tree only through their parents or guardians.", "Parental or guardian consent is given through the parent's or guardian's approved account within the app, after verification of their relationship to the minor and their status as the minor's parent or guardian. The consent is recorded in the app's records in a manner that evidences that it was given, its date, and its scope.", "Minors may be included in the family tree in accordance with the established rules, with due regard for their privacy and the protection of their personal data, and with any required consents obtained.", "Parents or guardians may submit requests to correct, update, hide, or delete a minor's personal data. Such requests are reviewed in accordance with the Privacy Policy and applicable regulations."]}, {"id": "account", "title": "User Obligations", "lines": ["When registering with and using the Al-Mohammad Ali Family app, users must provide true, accurate, and up-to-date information and must not impersonate others or provide misleading information about their identity or their relationship to the family.", "Users must use the app for legitimate family purposes, respect the privacy and rights of other members, and keep their verification codes and means of accessing their account confidential.", "Copying, extracting, publishing, or sharing outside the app any member's personal data or photos, or family tree information, is prohibited except with the consent of the data subjects concerned or on another lawful basis.", "Using the app to market or commercially promote products and services is prohibited. This does not apply to announcements about non-commercial family events and activities that have been reviewed and approved by the app administration.", "Posting content that is offensive, defamatory, threatening, invasive of others' privacy, or in breach of applicable regulations is also prohibited.", "The app has zero tolerance for abusive or inappropriate content and for abusive users. Acceptance of these rules is a condition for creating an account and using the app.", "Users are responsible for the content they submit or post, within the limits of their liability as established by law.", "In the event of a violation, the app administration may take appropriate action according to its nature and severity, ranging from a warning, to restriction of permissions, to suspension or termination of membership. Immediate action may be taken in the case of a serious violation that requires protecting members or their data, and the user may appeal the decision in accordance with the established procedures."]}, {"id": "content", "title": "Family Content and Posts", "lines": ["The Al-Mohammad Ali Family app allows approved members to submit news and announcements about family events and activities, in accordance with the services and permissions available in the app.", "Posts submitted by members are subject to review and approval by the app administration before they are published, to confirm that they are appropriate to the app's purposes and comply with the rules of use.", "Members whom the app administration has expressly granted direct-posting permission are exempt from the prior-approval requirement; however, their posts remain subject to subsequent review and content moderation procedures.", "Users must ensure that the information they submit is accurate, respect the privacy of the persons featured in a post, and not publish others' photos or personal data without their consent or another lawful basis that permits it.", "The app administration may reject non-compliant posts, request changes before publication, or correct, hide, or delete posts after publication where there is a legitimate reason to do so.", "Users may request that their post be edited or deleted. Such requests are handled in accordance with the established procedures, with due regard for the rights of the persons featured in the content.", "Members may report abusive content or content that violates the rules of use through the reporting tools provided in the app. The administration will review reports and take appropriate action within no more than twenty-four (24) hours, including removing the offending content and, where necessary, restricting the permissions of, or blocking access by, the offending user.", "Every member may block any other user from within the app, which prevents that user's content from appearing to them and prevents that user from contacting them. The app administration is notified of blocks so that it can review the relevant content where necessary."]}, {"id": "tree", "title": "Management of the Family Tree and Lineage Data", "lines": ["The Al-Mohammad Ali Family app aims to document the family tree and preserve family ties by displaying information drawn from family sources, genealogical charts, historical documents, and approved data.", "Approved members may submit requests to add their children and other individuals connected to them by a recognised family relationship within the family tree, in accordance with the permissions and rules set out in the app. Adding any other person requires a special request to the app administration for consideration.", "Requests to add individuals or to amend or correct their data are subject to review and verification by the app administration before they are approved and the changes appear in the family tree.", "Users must take care to ensure the accuracy and correctness of information about lineage and family relationships, and must not knowingly provide misleading or undocumented data.", "The app administration may request the supporting information or documents needed to verify requests, with due regard for the privacy of data subjects and without collecting more information than is necessary for verification.", "The display of information in the family tree does not constitute official proof of lineage and is not a substitute for documents and records issued by the competent authorities.", "Data subjects or their legal representatives may submit requests to correct, update, hide, or delete their information. Such requests are handled in accordance with the Privacy Policy, the established rules, and applicable regulations."]}, {"id": "admin", "title": "Administrative and Moderation Powers", "lines": ["The Al-Mohammad Ali Family app administration oversees the operation of the app, organises its services, and manages memberships, permissions, and family content in a manner that serves the app's objectives and safeguards the integrity of information and the privacy of members.", "Administrative and moderation permissions are granted to persons authorised by the app administration according to their duties and responsibilities, and they may not use these permissions beyond the authorised purposes.", "The app administration and its moderators, each within the limits of their permissions, may review requests for membership, additions, and amendments, examine content and reports, and take appropriate action to address violations in accordance with the rules of use.", "The administration may modify or restrict members' permissions, or suspend or terminate membership, where there are legitimate reasons to do so, ensuring that the action taken is proportionate to the nature and severity of the violation.", "Administrators and moderators must keep confidential the data they access in the course of their duties and must not disclose it or use it for personal gain or for unauthorised purposes.", "Users may appeal administrative decisions concerning their membership, permissions, or content. The app administration will review and respond to the appeal within no more than seven (7) calendar days from the date it is received, and will inform the user of the outcome through the means of communication available in the app."]}, {"id": "suspension", "title": "Suspension and Termination of Membership", "lines": ["The Al-Mohammad Ali Family app administration may temporarily suspend or terminate a user's membership if the user violates the rules of use, provides misleading information, misuses the app's services or the permissions granted to them, or engages in any conduct that may harm the security of the app or the privacy of its members.", "In taking such action, the nature, severity, and recurrence of the violation are taken into account. The administration may take immediate measures where there is an actual risk to the security of the app or the integrity of members' data, without prejudice to the user's right of appeal.", "The administration determines the length of a temporary suspension according to the nature and severity of the violation and reviews whether continued suspension is necessary. A suspension may be extended only for a justified reason, and the user will be informed accordingly.", "The user will be informed of the reason for the suspension or termination of their membership and of the action taken against them through the available means of communication, unless a legitimate legal or security reason prevents this.", "Users may appeal a decision to suspend or terminate their membership. The app administration will review and respond to the appeal within seven (7) calendar days from the date it is received, in accordance with the established procedures.", "Suspension or termination of membership does not constitute automatic deletion of the account or the personal data associated with it, and the user retains the right to request deletion of their account in accordance with Section 9 of the Privacy Policy.", "Termination of membership does not necessarily result in the deletion of lineage data from the family tree; only the name and family relationship may be retained, where permitted under the Privacy Policy and applicable regulations."]}, {"id": "ip", "title": "Intellectual Property Rights", "lines": ["The intellectual property rights in the name, logo, design, interfaces, software, and databases of the Al-Mohammad Ali Family app belong, to the extent permitted by law, to the owner of the app or to the rights holders who have licensed the use of their works.", "The app may not be copied, and no protected component of it may be reproduced, modified, distributed, or exploited for commercial purposes, without the prior consent of the rights holder.", "Users retain their lawful rights in the original photos, text, and other content they submit through the app, and publishing such content does not transfer its ownership to the app administration.", "Users grant the app administration a non-exclusive licence, limited to legitimate family purposes, to store, display, and process the content they submit to the extent necessary to operate the app's services and provide them to approved members, subject to the Privacy Policy and the rights of data subjects.", "Names, historical facts, and genealogical information are not, in themselves, the exclusive intellectual property of the app, without prejudice to any rights that may subsist in legally protected works, photos, or databases.", "Users must not post any content that infringes the intellectual property rights of others. Rights holders may submit reports to the app administration requesting the review or removal of infringing content."]}, {"id": "updates", "title": "Amendments to the Rules of Use", "lines": ["The Al-Mohammad Ali Family app administration reserves the right to amend or update these Terms and Rules of Use when necessary, in line with the development of the app's services, regulatory and legal requirements, or the measures needed to protect members and their data.", "The app administration will publish the updated version of the rules of use within the app, stating the date of the last update, and will notify members of material changes at least fourteen (14) calendar days before they take effect.", "The advance notice period does not apply to changes required to address urgent security risks or to comply with legal obligations that require immediate application; users will be informed of such changes as soon as possible.", "Where changes require the user's fresh consent under applicable regulations, the user's continued use of the app will not alone be treated as consent to those changes.", "Changes will not apply retroactively in a way that diminishes the rights users have under applicable laws and regulations.", "Users who do not wish to continue under the updated rules may stop using the app and request deletion of their account in accordance with the Privacy Policy."]}, {"id": "law", "title": "Governing Law and Dispute Resolution", "lines": ["These Terms and Rules of Use of the Al-Mohammad Ali Family app are governed by and construed in accordance with the laws and regulations in force in the State of Kuwait, subject to mandatory legal provisions and the applicable agreements governing distribution of the app through the Apple App Store.", "The app administration seeks to resolve complaints and disputes arising from the use of its services amicably, by receiving and examining complaints and communicating with the parties concerned.", "Users may submit a complaint about the services, content, or decisions relating to their membership. The app administration will review and respond to the complaint within seven (7) calendar days from the date it is received.", "If an amicable settlement cannot be reached, either party may refer the matter to the competent courts of the State of Kuwait in accordance with the jurisdictional rules established by law, without any requirement to exhaust amicable settlement procedures and without prejudice to the rights of litigation established by law.", "Apple is not a party to these rules governing the family services provided by the app, and bears no obligation to manage the family tree, review content, or resolve disputes between members, without prejudice to any obligations or rights established under the applicable Apple agreements or relevant laws."]}, {"id": "contact", "title": "Contacting the App Administration", "lines": ["Users may contact the Al-Mohammad Ali Family app administration regarding enquiries, complaints, appeals, privacy requests, data correction, account deletion, and reports of violations via the official email address: info@almohali.com", "Contacting the administration by email is not a requirement for requesting account deletion, as a deletion request can be started directly from within the app in accordance with the Privacy Policy."]}]}]}$j$::jsonb, default_value = $j${"title": "Privacy & Use", "subtitle": "Privacy Policy and Terms and Rules of Use", "updated": "2026-10-28", "sections": [{"key": "privacy", "title": "Privacy Policy", "items": [{"id": "collect", "title": "Collection of Personal Data", "lines": ["The Al-Mohammad Ali Family app collects the personal data required to create a user account and verify the user's mobile phone number. This includes full name, mobile phone number, date of birth, gender, and profile photo, all of which are mandatory to complete registration.", "Users may optionally add their email address.", "The mobile phone number is used to sign in by sending a verification code to the registered number. Verifying ownership of a phone number does not, by itself, constitute verification of personal identity or of a claimed family relationship.", "Personal data is stored and processed only to the extent necessary to create and manage the account and to provide the app's services, in accordance with this Privacy Policy."]}, {"id": "relatives", "title": "Data on Family Members and Relatives", "lines": ["The Al-Mohammad Ali Family app retains data about family members and their relatives in order to document the family tree, preserve family ties, and make family information easier to access.", "This data includes names, family relationships, dates of birth and death, photos, and other family information required by the app's services.", "This data may be drawn from family sources, genealogical charts, and historical documents, or added by users in accordance with the permissions established in the app.", "Access to the data displayed in the family tree, including data relating to living persons, is limited to approved members, subject to the controls established to protect privacy.", "Users may submit requests to add or amend data on family members. Such requests are subject to review and approval by the app administration before they take effect.", "When submitting data, users must respect the privacy of others and must not add personal information or photos without the consent of the persons concerned or another lawful basis that permits it.", "The privacy of living persons and minors is taken into account when their data is collected or displayed in the family tree. Information is displayed only to the extent necessary to fulfil the app's purposes, in accordance with the established permissions and the lawful basis for processing.", "The app does not create accounts for children under the age of thirteen (13). Their data is limited to what their parents or guardians add to the family tree in accordance with the established controls.", "Data subjects or, where applicable, the parents or guardians of minors may request that data be corrected, updated, hidden, or deleted. Such requests are reviewed in accordance with the established controls and applicable regulations."]}, {"id": "auto", "title": "Automatically Collected Data", "lines": ["The Al-Mohammad Ali Family app automatically collects certain technical data while the app is in use, including device type and operating system, user activity logs, sign-in attempts, error and crash reports, and statistics on usage of and interaction with the app's sections and services.", "This data is used to strengthen app security and protect user accounts, monitor performance, detect and fix technical problems, and analyse service usage in order to develop the services and improve the user experience.", "The app does not collect the user's geographic location for tracking or location purposes.", "The app does not track users across third-party apps or websites, and does not share their data with data brokers or advertising networks.", "The app accesses the device camera or photo library only when the user chooses to take or upload a photo and after the user grants the necessary permission in the device settings. The user may withdraw this permission at any time."]}, {"id": "why", "title": "Purposes of Data Collection and Use", "lines": ["The Al-Mohammad Ali Family app collects and processes personal data for the purposes necessary to provide its services and manage its operations, including creating and managing user accounts, verifying phone numbers, documenting the family tree and family ties, managing news, events, and posts, and sending notifications related to the app's services.", "Data is also used to strengthen account security, protect information, monitor performance, resolve technical faults, and analyse service usage in order to develop the app and improve the user experience.", "The app allows family members to submit announcements about non-commercial family events and activities. Such announcements are subject to prior review and approval by the app administration before publication, in accordance with the established controls.", "The app does not permit members' data to be used for commercial advertising, marketing, or ad targeting, and does not sell users' personal data or give advertisers access to it."]}, {"id": "who", "title": "Access to Personal Data", "lines": ["Access to the data and information displayed in the Al-Mohammad Ali Family app is limited to approved family members, in accordance with the permissions and privacy settings established in the app.", "Users may control the visibility of their profile data, including their profile photo, date of birth, and other information, through the privacy settings available to them.", "Users may show or hide their mobile phone number from approved family members. This does not affect the use of the number for signing in and account management.", "Authorised administrators of the app may access only the data necessary to perform their duties, including managing memberships, reviewing requests and reports, and moderating content. They must keep such information confidential and must not use it beyond the authorised purposes."]}, {"id": "share", "title": "Sharing Data with Service Providers", "lines": ["The Al-Mohammad Ali Family app is committed to protecting users' personal data and does not sell it or share it with third parties for marketing or commercial advertising purposes.", "The app relies on the technical service providers needed to operate it and deliver its services, including Supabase and Firebase for data management and related technical functions, Apple for push notifications, and SMS providers for verifying phone numbers and completing sign-in.", "Data shared with service providers is limited to the information needed to provide the relevant services, and appropriate measures are taken to keep it confidential and protect it from unauthorised access, use, or disclosure.", "Service providers with whom data is shared must provide a level of protection similar or equivalent to that set out in this Policy and may not use the data for any purpose other than providing the relevant service.", "Personal data may be stored or processed on servers located outside the State of Kuwait, depending on the hosting locations and technical infrastructure of the service providers, subject to data protection requirements and applicable regulations.", "Data may be disclosed to the competent authorities where required by law or by orders issued by the competent authorities."]}, {"id": "otp", "title": "Sign-In and Account Protection", "lines": ["The Al-Mohammad Ali Family app uses mobile phone sign-in, sending a one-time verification code (OTP) by text message (SMS) to the registered number.", "The verification code may be used only once and expires five minutes after it is issued.", "The app applies security measures to limit attempts to enter incorrect verification codes, helping to protect user accounts and prevent unauthorised access.", "Users must keep their verification code confidential, must not share it with others, and must notify the app administration if they suspect any attempt to gain unauthorised access to their account."]}, {"id": "security", "title": "Information Security and Data Protection", "lines": ["The Al-Mohammad Ali Family app protects users' personal data by applying appropriate technical and organisational measures to reduce the risk of unauthorised access to, or unlawful use, alteration, or disclosure of, information.", "Data is transmitted between the app and its servers over encrypted connections using secure communication protocols (HTTPS/TLS), and is stored and processed using approved technical services, including Supabase and Firebase.", "The app uses a permissions system that defines the levels of access granted to users, moderators, and administrators, ensuring that viewing and managing data is restricted according to the duties and permissions assigned to each group.", "Measures are also applied to protect stored photos and files and to restrict access to them by unauthorised persons.", "Although appropriate security measures are taken, absolute protection of data against all technical risks and threats cannot be guaranteed."]}, {"id": "delete", "title": "Deletion of Account and Personal Data", "lines": ["Users may request deletion of their account through the dedicated option in the Al-Mohammad Ali Family app settings. The request is referred to the app administration, which will take the necessary steps to complete the deletion within no more than seven (7) calendar days from the date the request is received.", "Once account deletion is complete, the personal data associated with the account is removed, including the mobile phone number, email address, profile photo, and posts and comments, subject to any legal obligations that require certain data to be retained.", "Deleting an account does not require removing all information about the user from the family tree. The name and family relationship may be retained to the extent necessary to preserve the lineage, provided there is a lawful basis for retaining this information.", "Data subjects may submit a separate request to correct, hide, or delete their information in the family tree. Data that is the subject of a request to hide or delete is temporarily hidden from other members while the request is under review, until an appropriate decision is made in accordance with the established controls and applicable regulations.", "Users may withdraw their consent to the processing of their data at any time by changing the privacy settings in the app, turning off notifications in the device settings, or requesting deletion of their account. Withdrawal of consent does not affect the lawfulness of processing carried out before it was withdrawn.", "The app does not retain personal data for longer than necessary to fulfil the purposes for which it was collected, unless a legal obligation or lawful basis permits it to be retained for a longer period.", "Retention periods for usage logs, technical data, and backups are determined by the nature of the data, the purpose of processing, security requirements, and applicable regulations. Such data is deleted or anonymised once it is no longer needed, in accordance with the established technical procedures.", "The app administration will inform the user of the outcome of a request to delete the account or personal data through the available means of communication, with due regard for the rights of data subjects and applicable regulations."]}, {"id": "privacy_contact", "title": "Contacting the App Administration", "lines": ["Users may contact the Al-Mohammad Ali Family app administration regarding enquiries, complaints, privacy requests, data correction, account deletion, and reports of violations via the official email address: info@almohali.com", "Contacting the administration by email is not an additional requirement for requesting account deletion, as a deletion request can be started directly from within the app in accordance with this Policy."]}]}, {"key": "terms", "title": "Terms and Rules of Use", "items": [{"id": "eligibility", "title": "Scope of Use and Membership", "lines": ["The Al-Mohammad Ali Family app is intended for members of the family and their relatives, in accordance with the membership rules established by the app administration. It aims to document family ties, strengthen communication among family members, and provide services and information related to family affairs.", "Joining the app is subject to registration and verification of applicants' eligibility. Creating an account or completing registration does not constitute automatic approval of membership; the app administration reviews applications to join, verifies applicants' eligibility, and approves their membership in accordance with the established rules.", "Persons aged thirteen (13) or over but under eighteen (18) may create their own account in the app, provided that explicit, documented consent is obtained from their parent or guardian before the account is activated, in addition to the app administration's approval of the membership application.", "Persons under the age of thirteen (13) may not create an account in the app. They may be included in the family tree only through their parents or guardians.", "Parental or guardian consent is given through the parent's or guardian's approved account within the app, after verification of their relationship to the minor and their status as the minor's parent or guardian. The consent is recorded in the app's records in a manner that evidences that it was given, its date, and its scope.", "Minors may be included in the family tree in accordance with the established rules, with due regard for their privacy and the protection of their personal data, and with any required consents obtained.", "Parents or guardians may submit requests to correct, update, hide, or delete a minor's personal data. Such requests are reviewed in accordance with the Privacy Policy and applicable regulations."]}, {"id": "account", "title": "User Obligations", "lines": ["When registering with and using the Al-Mohammad Ali Family app, users must provide true, accurate, and up-to-date information and must not impersonate others or provide misleading information about their identity or their relationship to the family.", "Users must use the app for legitimate family purposes, respect the privacy and rights of other members, and keep their verification codes and means of accessing their account confidential.", "Copying, extracting, publishing, or sharing outside the app any member's personal data or photos, or family tree information, is prohibited except with the consent of the data subjects concerned or on another lawful basis.", "Using the app to market or commercially promote products and services is prohibited. This does not apply to announcements about non-commercial family events and activities that have been reviewed and approved by the app administration.", "Posting content that is offensive, defamatory, threatening, invasive of others' privacy, or in breach of applicable regulations is also prohibited.", "The app has zero tolerance for abusive or inappropriate content and for abusive users. Acceptance of these rules is a condition for creating an account and using the app.", "Users are responsible for the content they submit or post, within the limits of their liability as established by law.", "In the event of a violation, the app administration may take appropriate action according to its nature and severity, ranging from a warning, to restriction of permissions, to suspension or termination of membership. Immediate action may be taken in the case of a serious violation that requires protecting members or their data, and the user may appeal the decision in accordance with the established procedures."]}, {"id": "content", "title": "Family Content and Posts", "lines": ["The Al-Mohammad Ali Family app allows approved members to submit news and announcements about family events and activities, in accordance with the services and permissions available in the app.", "Posts submitted by members are subject to review and approval by the app administration before they are published, to confirm that they are appropriate to the app's purposes and comply with the rules of use.", "Members whom the app administration has expressly granted direct-posting permission are exempt from the prior-approval requirement; however, their posts remain subject to subsequent review and content moderation procedures.", "Users must ensure that the information they submit is accurate, respect the privacy of the persons featured in a post, and not publish others' photos or personal data without their consent or another lawful basis that permits it.", "The app administration may reject non-compliant posts, request changes before publication, or correct, hide, or delete posts after publication where there is a legitimate reason to do so.", "Users may request that their post be edited or deleted. Such requests are handled in accordance with the established procedures, with due regard for the rights of the persons featured in the content.", "Members may report abusive content or content that violates the rules of use through the reporting tools provided in the app. The administration will review reports and take appropriate action within no more than twenty-four (24) hours, including removing the offending content and, where necessary, restricting the permissions of, or blocking access by, the offending user.", "Every member may block any other user from within the app, which prevents that user's content from appearing to them and prevents that user from contacting them. The app administration is notified of blocks so that it can review the relevant content where necessary."]}, {"id": "tree", "title": "Management of the Family Tree and Lineage Data", "lines": ["The Al-Mohammad Ali Family app aims to document the family tree and preserve family ties by displaying information drawn from family sources, genealogical charts, historical documents, and approved data.", "Approved members may submit requests to add their children and other individuals connected to them by a recognised family relationship within the family tree, in accordance with the permissions and rules set out in the app. Adding any other person requires a special request to the app administration for consideration.", "Requests to add individuals or to amend or correct their data are subject to review and verification by the app administration before they are approved and the changes appear in the family tree.", "Users must take care to ensure the accuracy and correctness of information about lineage and family relationships, and must not knowingly provide misleading or undocumented data.", "The app administration may request the supporting information or documents needed to verify requests, with due regard for the privacy of data subjects and without collecting more information than is necessary for verification.", "The display of information in the family tree does not constitute official proof of lineage and is not a substitute for documents and records issued by the competent authorities.", "Data subjects or their legal representatives may submit requests to correct, update, hide, or delete their information. Such requests are handled in accordance with the Privacy Policy, the established rules, and applicable regulations."]}, {"id": "admin", "title": "Administrative and Moderation Powers", "lines": ["The Al-Mohammad Ali Family app administration oversees the operation of the app, organises its services, and manages memberships, permissions, and family content in a manner that serves the app's objectives and safeguards the integrity of information and the privacy of members.", "Administrative and moderation permissions are granted to persons authorised by the app administration according to their duties and responsibilities, and they may not use these permissions beyond the authorised purposes.", "The app administration and its moderators, each within the limits of their permissions, may review requests for membership, additions, and amendments, examine content and reports, and take appropriate action to address violations in accordance with the rules of use.", "The administration may modify or restrict members' permissions, or suspend or terminate membership, where there are legitimate reasons to do so, ensuring that the action taken is proportionate to the nature and severity of the violation.", "Administrators and moderators must keep confidential the data they access in the course of their duties and must not disclose it or use it for personal gain or for unauthorised purposes.", "Users may appeal administrative decisions concerning their membership, permissions, or content. The app administration will review and respond to the appeal within no more than seven (7) calendar days from the date it is received, and will inform the user of the outcome through the means of communication available in the app."]}, {"id": "suspension", "title": "Suspension and Termination of Membership", "lines": ["The Al-Mohammad Ali Family app administration may temporarily suspend or terminate a user's membership if the user violates the rules of use, provides misleading information, misuses the app's services or the permissions granted to them, or engages in any conduct that may harm the security of the app or the privacy of its members.", "In taking such action, the nature, severity, and recurrence of the violation are taken into account. The administration may take immediate measures where there is an actual risk to the security of the app or the integrity of members' data, without prejudice to the user's right of appeal.", "The administration determines the length of a temporary suspension according to the nature and severity of the violation and reviews whether continued suspension is necessary. A suspension may be extended only for a justified reason, and the user will be informed accordingly.", "The user will be informed of the reason for the suspension or termination of their membership and of the action taken against them through the available means of communication, unless a legitimate legal or security reason prevents this.", "Users may appeal a decision to suspend or terminate their membership. The app administration will review and respond to the appeal within seven (7) calendar days from the date it is received, in accordance with the established procedures.", "Suspension or termination of membership does not constitute automatic deletion of the account or the personal data associated with it, and the user retains the right to request deletion of their account in accordance with Section 9 of the Privacy Policy.", "Termination of membership does not necessarily result in the deletion of lineage data from the family tree; only the name and family relationship may be retained, where permitted under the Privacy Policy and applicable regulations."]}, {"id": "ip", "title": "Intellectual Property Rights", "lines": ["The intellectual property rights in the name, logo, design, interfaces, software, and databases of the Al-Mohammad Ali Family app belong, to the extent permitted by law, to the owner of the app or to the rights holders who have licensed the use of their works.", "The app may not be copied, and no protected component of it may be reproduced, modified, distributed, or exploited for commercial purposes, without the prior consent of the rights holder.", "Users retain their lawful rights in the original photos, text, and other content they submit through the app, and publishing such content does not transfer its ownership to the app administration.", "Users grant the app administration a non-exclusive licence, limited to legitimate family purposes, to store, display, and process the content they submit to the extent necessary to operate the app's services and provide them to approved members, subject to the Privacy Policy and the rights of data subjects.", "Names, historical facts, and genealogical information are not, in themselves, the exclusive intellectual property of the app, without prejudice to any rights that may subsist in legally protected works, photos, or databases.", "Users must not post any content that infringes the intellectual property rights of others. Rights holders may submit reports to the app administration requesting the review or removal of infringing content."]}, {"id": "updates", "title": "Amendments to the Rules of Use", "lines": ["The Al-Mohammad Ali Family app administration reserves the right to amend or update these Terms and Rules of Use when necessary, in line with the development of the app's services, regulatory and legal requirements, or the measures needed to protect members and their data.", "The app administration will publish the updated version of the rules of use within the app, stating the date of the last update, and will notify members of material changes at least fourteen (14) calendar days before they take effect.", "The advance notice period does not apply to changes required to address urgent security risks or to comply with legal obligations that require immediate application; users will be informed of such changes as soon as possible.", "Where changes require the user's fresh consent under applicable regulations, the user's continued use of the app will not alone be treated as consent to those changes.", "Changes will not apply retroactively in a way that diminishes the rights users have under applicable laws and regulations.", "Users who do not wish to continue under the updated rules may stop using the app and request deletion of their account in accordance with the Privacy Policy."]}, {"id": "law", "title": "Governing Law and Dispute Resolution", "lines": ["These Terms and Rules of Use of the Al-Mohammad Ali Family app are governed by and construed in accordance with the laws and regulations in force in the State of Kuwait, subject to mandatory legal provisions and the applicable agreements governing distribution of the app through the Apple App Store.", "The app administration seeks to resolve complaints and disputes arising from the use of its services amicably, by receiving and examining complaints and communicating with the parties concerned.", "Users may submit a complaint about the services, content, or decisions relating to their membership. The app administration will review and respond to the complaint within seven (7) calendar days from the date it is received.", "If an amicable settlement cannot be reached, either party may refer the matter to the competent courts of the State of Kuwait in accordance with the jurisdictional rules established by law, without any requirement to exhaust amicable settlement procedures and without prejudice to the rights of litigation established by law.", "Apple is not a party to these rules governing the family services provided by the app, and bears no obligation to manage the family tree, review content, or resolve disputes between members, without prejudice to any obligations or rights established under the applicable Apple agreements or relevant laws."]}, {"id": "contact", "title": "Contacting the App Administration", "lines": ["Users may contact the Al-Mohammad Ali Family app administration regarding enquiries, complaints, appeals, privacy requests, data correction, account deletion, and reports of violations via the official email address: info@almohali.com", "Contacting the administration by email is not a requirement for requesting account deletion, as a deletion request can be started directly from within the app in accordance with the Privacy Policy."]}]}]}$j$::jsonb where key = 'legal_content_en';
